parameters.jsCode:
const lead = $('Loop each lead').first().json;
const msgs = $('Fetch last 10 messages').all().map(i => i.json).filter(m => m && m.id); // newest first
const qual = $('Fetch qualification').first()?.json || {};

// Twilio sandbox allows free-form messages only within 24h of the lead's last INBOUND message.
// 23h threshold leaves a safety margin for clock skew and run delay.
const lastIn = msgs.find(m => m.direction === 'in');
const hoursSince = lastIn ? (Date.now() - new Date(lastIn.created_at).getTime()) / 3600000 : null;
const windowOpen = hoursSince !== null && hoursSince < 23;

// Cadence: gaps[k] = days until the next follow-up once k follow-ups have been sent.
// WF2 already schedules follow-up 1 (warm +1 day, cold +3 days). Warm max 3, cold max 2.
const n = (lead.followup_count || 0) + 1;
const gaps = lead.score === 'warm' ? [1, 3, 7] : lead.score === 'cold' ? [3, 7] : [];
const nextDays = gaps[n];
const nextAt = nextDays ? new Date(Date.now() + nextDays * 86400000).toISOString() : null;

// Reply language: code decides from the lead's last 3 inbound messages, the model only follows it.
// Any Devanagari in them -> Hindi. Latin-only -> English. Stored preference is used only when there is no inbound message.
const recentIn = msgs.filter(m => m.direction === 'in').slice(0, 3);
const hasDevanagari = recentIn.some(m => /[\u0900-\u097F]/.test(m.content || ''));
let lang;
if (hasDevanagari) lang = 'hi';
else if (recentIn.length > 0) lang = 'en';
else lang = lead.preferred_language === 'hi' ? 'hi' : 'en';
const langName = lang === 'hi' ? 'Hindi' : 'English';

const SYSTEM_PROMPT = 'You are a real estate assistant following up with a lead on WhatsApp. This is an automated follow-up, not a reply to a new message.\n\n' +
'The lead has not replied recently. Your job is to send a short, friendly nudge to re-engage them. Base your follow-up on what you know about them.\n\n' +
'Rules:\n' +
'1. Keep it very short: 1-2 sentences max. This is a nudge, not a pitch.\n' +
'2. Reference something specific from the conversation if possible (their budget, location interest, etc.).\n' +
'3. Do NOT re-introduce yourself or re-explain the service.\n' +
'4. Do NOT pressure them. One gentle question is ideal.\n' +
'5. Write in the language named in the last line of the user prompt.\n' +
'6. If you have nothing specific to reference, ask a simple open question like \"Still looking for a property?\"\n' +
'7. Never promise, schedule or confirm a call, visit or callback.\n\n' +
'Return ONLY a single JSON object, no markdown, no explanation:\n' +
'{\"reply_text\": \"your follow-up message\", \"language\": \"hi\" or \"en\"}';

const fields = ['budget', 'location', 'property_type', 'timeline'];
const known = fields.filter(f => qual[f]);
let knownText = '';
if (known.length) knownText = 'What we already know about the lead:\n' + known.map(f => '- ' + f + ': ' + qual[f]).join('\n') + '\n';

let history = '';
for (const m of [...msgs].reverse()) history += (m.direction === 'out' ? 'Agent' : 'Lead') + ': ' + m.content + '\n';

const userPrompt = 'Lead name: ' + (lead.name || 'unknown') + '\n' +
'Lead score: ' + lead.score + '\n' +
'This is automated follow-up ' + n + ' of ' + gaps.length + '.\n\n' +
knownText + '\nConversation so far:\n' + history +
'\nWrite the follow-up nudge. Write reply_text in ' + langName + ' and set "language" to "' + lang + '".';

return [{ json: {
  lead_id: lead.id,
  phone: lead.phone,
  name: lead.name,
  score: lead.score,
  new_count: n,
  next_follow_up_at: nextAt,
  window_open: windowOpen,
  hours_since_inbound: hoursSince === null ? null : Math.round(hoursSince * 10) / 10,
  fail_reason: windowOpen ? null : 'outside_24h_window',
  system_prompt: SYSTEM_PROMPT,
  user_prompt: userPrompt
} }];

