={{ JSON.stringify({
  model: "gpt-4o-mini",
  messages: [
    { role: "system", content: $json.system_prompt },
    { role: "user", content: $json.user_prompt }
  ],
  response_format: { type: "json_object" },
  temperature: 0.3
}) }}

parameters.jsCode:
const res = $input.first().json;
const raw = res.choices?.[0]?.message?.content ?? '';

let ok = false, error = null, reply = '', lang = null;
try {
  const d = JSON.parse(raw);
  if (typeof d.reply_text !== 'string' || !d.reply_text.trim()) throw new Error('reply_text missing');
  if (!['hi', 'en'].includes(d.language)) throw new Error('bad language');
  reply = d.reply_text.trim();
  if (reply.length > 400) throw new Error('reply too long for a nudge');
  lang = d.language;
  ok = true;
} catch (e) {
  error = e.message;
}

// Score, status and counters are never taken from the model. Code owns them.
return [{ json: { parse_ok: ok, reply_text: reply, language: lang, fail_reason: ok ? null : 'llm_bad_output: ' + error } }];

